-- Reference baseline, NOT applied. PostgreSQL + pgvector required.
-- IDs generated by the platform. Framework checkpoint tables managed separately.
CREATE EXTENSION IF NOT EXISTS vector;
CREATE SCHEMA IF NOT EXISTS platform;
SET search_path TO platform, public;

CREATE TABLE principals (
  id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('user','service')),
  display_name text NOT NULL, disabled_at timestamptz,
  responsible_user_id uuid, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE users (
  principal_id uuid PRIMARY KEY REFERENCES principals(id),
  login text NOT NULL UNIQUE, password_hash text NOT NULL,
  must_change_password boolean NOT NULL DEFAULT true
);
CREATE TABLE activation_tokens (
  id uuid PRIMARY KEY, principal_id uuid NOT NULL REFERENCES users(principal_id),
  token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL,
  consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE principals ADD FOREIGN KEY (responsible_user_id) REFERENCES users(principal_id);
CREATE TABLE role_bindings (
  principal_id uuid REFERENCES principals(id),
  role text CHECK(role IN ('admin','creator','user')),
  PRIMARY KEY(principal_id,role)
);
CREATE TABLE sessions (
  token_hash text PRIMARY KEY, principal_id uuid NOT NULL REFERENCES principals(id),
  csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz
);
CREATE TABLE api_keys (
  id uuid PRIMARY KEY, principal_id uuid NOT NULL REFERENCES principals(id),
  key_hash text NOT NULL UNIQUE, scopes text[] NOT NULL,
  expires_at timestamptz NOT NULL, revoked_at timestamptz
);
CREATE TABLE resource_grants (
  id uuid PRIMARY KEY, principal_id uuid NOT NULL REFERENCES principals(id),
  resource_type text NOT NULL, resource_id uuid NOT NULL, action text NOT NULL,
  expires_at timestamptz,
  UNIQUE(principal_id,resource_type,resource_id,action)
);
CREATE INDEX grants_resource ON resource_grants(resource_type,resource_id,action);
CREATE TABLE policy_epochs (
  scope text PRIMARY KEY, revision bigint NOT NULL CHECK(revision>=0)
);
CREATE TABLE artifacts (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  object_key text NOT NULL UNIQUE, staging_object_key text UNIQUE, expected_sha256 text, purpose text NOT NULL,
  sha256 text, media_type text NOT NULL, size_bytes bigint CHECK(size_bytes>=0),
  state text NOT NULL CHECK(state IN ('uploading','scanning','ready','quarantined','deleted')),
  created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
  purged_at timestamptz
);
CREATE TABLE background_jobs (
  id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('artifact_finalize','route_request','tool_build','document_ingest','application_evaluate','model_validate','delete_content','catalog_index')),
  target_id uuid NOT NULL, owner_id uuid NOT NULL REFERENCES principals(id),
  expected_revision bigint, expected_sha256 text, dedup_key text NOT NULL,
  input_artifact_id uuid REFERENCES artifacts(id), result_artifact_id uuid REFERENCES artifacts(id),
  state text NOT NULL CHECK(state IN ('ready','leased','succeeded','failed','cancelled')),
  available_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_deadline timestamptz,
  worker_id text, attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),
  result_event_id uuid UNIQUE, error_code text, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(kind,dedup_key)
);
CREATE INDEX background_jobs_ready ON background_jobs(available_at,id) WHERE state='ready';
CREATE TABLE model_profile_versions (
  id uuid PRIMARY KEY, name text NOT NULL, provider text NOT NULL,
  model_id text NOT NULL, endpoint_ref text NOT NULL, secret_ref text NOT NULL,
  config jsonb NOT NULL, data_destination text NOT NULL,
  manifest_sha256 text NOT NULL UNIQUE, manifest_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  validation_state text NOT NULL DEFAULT 'pending' CHECK(validation_state IN ('pending','running','passed','failed')),
  evaluation_report_id uuid, revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tool_versions (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  source_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  input_schema jsonb NOT NULL, output_schema jsonb NOT NULL,
  dependency_lock jsonb NOT NULL, connector_versions jsonb NOT NULL DEFAULT '[]', image_digest text,
  risk_class text NOT NULL CHECK(risk_class IN ('pure','read','write')),
  state text NOT NULL CHECK(state IN ('submitted','building','ready','failed','revoked')),
  manifest_sha256 text NOT NULL UNIQUE, approved_by uuid REFERENCES users(principal_id),
  approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(state <> 'ready' OR image_digest IS NOT NULL)
);
CREATE TABLE applications (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  name text NOT NULL, active_version_id uuid, archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE application_drafts (
  application_id uuid PRIMARY KEY REFERENCES applications(id),
  revision bigint NOT NULL CHECK(revision>0), definition jsonb NOT NULL,
  layout jsonb NOT NULL DEFAULT '{}', capability_card jsonb NOT NULL DEFAULT '{}',
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE evaluation_reports (
  id uuid PRIMARY KEY, manifest_sha256 text NOT NULL,
  dataset_sha256 text NOT NULL, result_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  status text NOT NULL CHECK(status IN ('passed','failed','not_run')),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE model_profile_versions ADD FOREIGN KEY(evaluation_report_id) REFERENCES evaluation_reports(id);
CREATE TABLE publication_reviews (
  id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id),
  submitted_by uuid NOT NULL REFERENCES principals(id),
  snapshot jsonb NOT NULL, manifest_sha256 text NOT NULL,
  report_id uuid NOT NULL REFERENCES evaluation_reports(id),
  state text NOT NULL CHECK(state IN ('submitted','approved','rejected')),
  reviewer_id uuid REFERENCES principals(id), decided_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE application_versions (
  id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id),
  version_no integer NOT NULL CHECK(version_no>0), review_id uuid NOT NULL REFERENCES publication_reviews(id),
  manifest jsonb NOT NULL, manifest_sha256 text NOT NULL,
  manifest_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  capability_card jsonb NOT NULL, compiler_version text NOT NULL,
  worker_image_digest text NOT NULL, state_schema_version text NOT NULL,
  revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(application_id,version_no), UNIQUE(application_id,id)
);
ALTER TABLE applications ADD CONSTRAINT active_version_belongs_to_app
  FOREIGN KEY(id,active_version_id) REFERENCES application_versions(application_id,id);
CREATE TABLE version_dependencies (
  parent_version_id uuid REFERENCES application_versions(id),
  child_version_id uuid REFERENCES application_versions(id),
  PRIMARY KEY(parent_version_id,child_version_id), CHECK(parent_version_id<>child_version_id)
);
CREATE TABLE application_catalog_entries (
  application_version_id uuid PRIMARY KEY REFERENCES application_versions(id),
  search_text text NOT NULL, embedding_model_revision text, embedding vector,
  source_manifest_sha256 text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE execution_snapshots (
  id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('published','debug')),
  application_id uuid NOT NULL REFERENCES applications(id),
  application_version_id uuid REFERENCES application_versions(id), draft_revision bigint,
  owner_id uuid NOT NULL REFERENCES principals(id), manifest jsonb NOT NULL,
  manifest_sha256 text NOT NULL, manifest_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  compiler_version text NOT NULL, worker_image_digest text NOT NULL,
  state_schema_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  CHECK((kind='published' AND application_version_id IS NOT NULL AND draft_revision IS NULL)
     OR (kind='debug' AND application_version_id IS NULL AND draft_revision IS NOT NULL))
);
CREATE TABLE evaluation_jobs (
  id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('application','model')),
  owner_id uuid NOT NULL REFERENCES principals(id),
  background_job_id uuid NOT NULL UNIQUE REFERENCES background_jobs(id),
  snapshot_id uuid REFERENCES execution_snapshots(id), model_profile_version_id uuid REFERENCES model_profile_versions(id),
  dataset_artifact_id uuid NOT NULL REFERENCES artifacts(id), report_id uuid REFERENCES evaluation_reports(id),
  state text NOT NULL CHECK(state IN ('queued','running','succeeded','failed','cancelled')),
  error_code text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz,
  CHECK((kind='application' AND snapshot_id IS NOT NULL AND model_profile_version_id IS NULL)
     OR (kind='model' AND model_profile_version_id IS NOT NULL AND snapshot_id IS NULL))
);
CREATE TABLE conversations (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  revision bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE TABLE requests (
  id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id),
  owner_id uuid NOT NULL REFERENCES principals(id), input_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  state text NOT NULL CHECK(state IN ('queued','routing','awaiting_input','awaiting_selection','dispatched','cancelled','failed')),
  revision bigint NOT NULL DEFAULT 1, error_code text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE platform_model_calls (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  request_id uuid REFERENCES requests(id), background_job_id uuid REFERENCES background_jobs(id),
  model_profile_version_id uuid NOT NULL REFERENCES model_profile_versions(id),
  scope_key text NOT NULL, logical_key text NOT NULL, physical_attempt integer NOT NULL CHECK(physical_attempt>0),
  state text NOT NULL CHECK(state IN ('prepared','dispatching','succeeded','failed','unknown','cancelled')),
  result_artifact_id uuid REFERENCES artifacts(id), currency text NOT NULL,
  reserved_amount numeric(20,8) NOT NULL CHECK(reserved_amount>=0),
  charged_amount numeric(20,8) CHECK(charged_amount>=0), tokens_in bigint, tokens_out bigint,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK((request_id IS NULL) <> (background_job_id IS NULL)),
  UNIQUE(scope_key,logical_key,physical_attempt)
);
CREATE INDEX requests_queue ON requests(conversation_id,created_at,id);
CREATE TABLE interactions (
  id uuid PRIMARY KEY, request_id uuid NOT NULL REFERENCES requests(id),
  kind text NOT NULL CHECK(kind IN ('input','selection')),
  state text NOT NULL CHECK(state IN ('pending','answered','expired','invalidated')),
  proposal_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  response_artifact_id uuid REFERENCES artifacts(id), expires_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX one_pending_interaction ON interactions(request_id) WHERE state='pending';
CREATE TABLE runs (
  id uuid PRIMARY KEY, request_id uuid UNIQUE REFERENCES requests(id),
  conversation_id uuid REFERENCES conversations(id), parent_run_id uuid REFERENCES runs(id), parent_invocation_key text,
  owner_id uuid NOT NULL REFERENCES principals(id),
  kind text NOT NULL CHECK(kind IN ('published','debug')),
  execution_snapshot_id uuid NOT NULL REFERENCES execution_snapshots(id),
  application_version_id uuid REFERENCES application_versions(id),
  manifest_sha256 text NOT NULL, input_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  output_artifact_id uuid REFERENCES artifacts(id), checkpoint_thread_id uuid NOT NULL UNIQUE,
  state text NOT NULL CHECK(state IN ('queued','running','waiting_approval','waiting_children','cancelling','recovery_pending','needs_reconciliation','succeeded','failed','cancelled')),
  revision bigint NOT NULL DEFAULT 1, next_event_seq bigint NOT NULL DEFAULT 1,
  budget_limit numeric(20,8) NOT NULL CHECK(budget_limit>=0), currency text NOT NULL,
  phase text NOT NULL DEFAULT 'idle' CHECK(phase IN ('idle','executing','waiting','finalizing')),
  active_elapsed_ms bigint NOT NULL DEFAULT 0 CHECK(active_elapsed_ms>=0),
  cancel_requested_at timestamptz, error_code text, started_at timestamptz,
  finished_at timestamptz, deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(kind='debug' OR parent_run_id IS NOT NULL OR (request_id IS NOT NULL AND conversation_id IS NOT NULL)),
  CHECK((kind='published' AND application_version_id IS NOT NULL)
     OR (kind='debug' AND application_version_id IS NULL AND parent_run_id IS NULL AND request_id IS NULL)),
  CHECK(parent_run_id IS NULL OR (request_id IS NULL AND parent_invocation_key IS NOT NULL)),
  UNIQUE(parent_run_id,parent_invocation_key)
);
CREATE UNIQUE INDEX one_active_top_run_per_conversation ON runs(conversation_id)
 WHERE parent_run_id IS NULL AND state NOT IN ('succeeded','failed','cancelled');
CREATE INDEX runs_owner_time ON runs(owner_id,created_at DESC);
CREATE INDEX runs_parent ON runs(parent_run_id);
CREATE TABLE jobs (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id),
  kind text NOT NULL CHECK(kind IN ('start','resume')),
  state text NOT NULL CHECK(state IN ('ready','leased','held','completed','void')),
  available_at timestamptz NOT NULL DEFAULT now(), current_attempt_token uuid,
  resume_artifact_id uuid REFERENCES artifacts(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX one_live_job_per_run ON jobs(run_id) WHERE state IN ('ready','leased','held');
CREATE INDEX jobs_ready ON jobs(available_at,id) WHERE state='ready';
CREATE TABLE run_attempts (
  token uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), run_id uuid NOT NULL REFERENCES runs(id),
  worker_id text NOT NULL, execution_unit_id text NOT NULL,
  lease_deadline timestamptz NOT NULL, heartbeat_at timestamptz NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(), exited_at timestamptz,
  exit_evidence jsonb, checkpoint_connections jsonb NOT NULL DEFAULT '[]', revoked_at timestamptz,
  reported_result jsonb, reported_at timestamptz, checkpoint_id text
);
ALTER TABLE jobs ADD FOREIGN KEY(current_attempt_token) REFERENCES run_attempts(token);
CREATE TABLE quota_counters (
  scope text NOT NULL, dimension text NOT NULL,
  used integer NOT NULL CHECK(used>=0), capacity integer NOT NULL CHECK(capacity>=0),
  PRIMARY KEY(scope,dimension), CHECK(used<=capacity)
);
CREATE TABLE quota_allocations (
  id uuid PRIMARY KEY, scope text NOT NULL, dimension text NOT NULL,
  holder_key text NOT NULL, released_at timestamptz,
  FOREIGN KEY(scope,dimension) REFERENCES quota_counters(scope,dimension),
  UNIQUE(scope,dimension,holder_key)
);
CREATE TABLE node_attempts (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id),
  attempt_token uuid NOT NULL REFERENCES run_attempts(token), node_id text NOT NULL,
  invocation_path text NOT NULL, attempt_no integer NOT NULL CHECK(attempt_no>0),
  state text NOT NULL CHECK(state IN ('pending','running','waiting','succeeded','failed','skipped')),
  output_artifact_id uuid REFERENCES artifacts(id), error_code text,
  started_at timestamptz, finished_at timestamptz,
  UNIQUE(run_id,node_id,invocation_path,attempt_no)
);
CREATE TABLE operations (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id),
  logical_key text NOT NULL, capability_version text NOT NULL,
  capability_kind text NOT NULL CHECK(capability_kind IN ('model','tool','connector')),
  risk_class text NOT NULL CHECK(risk_class IN ('pure','read','write')),
  params_sha256 text NOT NULL, params_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  state text NOT NULL CHECK(state IN ('prepared','awaiting_approval','authorized','dispatching','succeeded','failed','unknown')),
  provider_idempotency_key text, receipt_artifact_id uuid REFERENCES artifacts(id),
  dispatched_at timestamptz, reconciled_by uuid REFERENCES principals(id),
  reconciliation_evidence_id uuid REFERENCES artifacts(id),
  UNIQUE(run_id,logical_key)
);
CREATE TABLE approvals (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id),
  operation_id uuid UNIQUE REFERENCES operations(id), node_key text NOT NULL,
  proposal_artifact_id uuid NOT NULL REFERENCES artifacts(id), params_sha256 text NOT NULL,
  approver_id uuid NOT NULL REFERENCES users(principal_id),
  state text NOT NULL CHECK(state IN ('pending','approved','rejected','expired','invalidated')),
  expires_at timestamptz NOT NULL, decided_at timestamptz,
  decided_by uuid REFERENCES principals(id), decision_key text,
  UNIQUE(run_id,node_key,params_sha256)
);
CREATE INDEX approvals_pending ON approvals(approver_id,expires_at) WHERE state='pending';
CREATE TABLE run_events (
  run_id uuid REFERENCES runs(id), seq bigint CHECK(seq>0), event_id uuid NOT NULL UNIQUE,
  type text NOT NULL, revision bigint NOT NULL, payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,seq)
);
CREATE TABLE usage_ledger (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id),
  budget_root_run_id uuid NOT NULL REFERENCES runs(id), operation_id uuid NOT NULL REFERENCES operations(id),
  entry_key text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('reserve','release','charge')),
  amount numeric(20,8) NOT NULL CHECK(amount>=0), currency text NOT NULL,
  tokens_in bigint, tokens_out bigint, price_version text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE run_artifacts (
  run_id uuid REFERENCES runs(id), artifact_id uuid REFERENCES artifacts(id),
  attempt_token uuid REFERENCES run_attempts(token), relation text NOT NULL,
  PRIMARY KEY(run_id,artifact_id)
);
CREATE TABLE memory_candidates (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(principal_id),
  application_id uuid NOT NULL REFERENCES applications(id),
  body_artifact_id uuid NOT NULL REFERENCES artifacts(id), source_run_id uuid REFERENCES runs(id),
  state text NOT NULL CHECK(state IN ('pending','confirmed','rejected','expired')),
  expires_at timestamptz NOT NULL
);
CREATE TABLE memories (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(principal_id),
  application_id uuid NOT NULL REFERENCES applications(id),
  body_artifact_id uuid NOT NULL REFERENCES artifacts(id),
  candidate_id uuid UNIQUE REFERENCES memory_candidates(id), revision bigint NOT NULL DEFAULT 1,
  confirmed_at timestamptz NOT NULL, deleted_at timestamptz
);
CREATE INDEX memories_scope ON memories(owner_id,application_id) WHERE deleted_at IS NULL;
CREATE TABLE memory_embeddings (
  memory_id uuid REFERENCES memories(id), memory_revision bigint NOT NULL,
  embedding_model_revision text NOT NULL, embedding vector,
  PRIMARY KEY(memory_id,memory_revision,embedding_model_revision)
);
CREATE TABLE knowledge_bases (
  id uuid PRIMARY KEY, name text NOT NULL, owner_id uuid NOT NULL REFERENCES principals(id),
  revision bigint NOT NULL DEFAULT 1, deleted_at timestamptz
);
CREATE TABLE knowledge_documents (
  id uuid PRIMARY KEY, knowledge_base_id uuid NOT NULL REFERENCES knowledge_bases(id),
  source_artifact_id uuid NOT NULL REFERENCES artifacts(id), revision bigint NOT NULL DEFAULT 1,
  state text NOT NULL CHECK(state IN ('uploaded','scanning','indexing','ready','failed','deleting','deleted')),
  parser_version text, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX documents_scope ON knowledge_documents(knowledge_base_id,state);
CREATE TABLE knowledge_chunks (
  id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES knowledge_documents(id),
  document_revision bigint NOT NULL, chunk_no integer NOT NULL,
  body_artifact_id uuid NOT NULL REFERENCES artifacts(id), citation jsonb NOT NULL,
  embedding_model_revision text NOT NULL, embedding vector,
  UNIQUE(document_id,document_revision,chunk_no)
);
CREATE TABLE diagnostic_grants (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(principal_id),
  grantee_id uuid NOT NULL REFERENCES principals(id), run_id uuid NOT NULL REFERENCES runs(id),
  purposes text[] NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz
);
CREATE TABLE audit_events (
  id uuid PRIMARY KEY, actor_id uuid REFERENCES principals(id), action text NOT NULL,
  resource_type text NOT NULL, resource_id uuid, metadata jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE idempotency_keys (
  principal_id uuid REFERENCES principals(id), method text, path text, key text,
  request_sha256 text NOT NULL, response_code integer, response_artifact_id uuid REFERENCES artifacts(id),
  expires_at timestamptz NOT NULL, PRIMARY KEY(principal_id,method,path,key)
);
CREATE TABLE outbox (
  id uuid PRIMARY KEY, kind text NOT NULL, aggregate_id uuid NOT NULL,
  payload jsonb NOT NULL, available_at timestamptz NOT NULL DEFAULT now(),
  delivered_at timestamptz, attempts integer NOT NULL DEFAULT 0
);
CREATE INDEX outbox_ready ON outbox(available_at,id) WHERE delivered_at IS NULL;
CREATE TABLE deletion_jobs (
  id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES principals(id),
  resource_type text NOT NULL, resource_id uuid NOT NULL, deletion_revision bigint NOT NULL,
  state text NOT NULL CHECK(state IN ('pending','running','completed','failed')),
  remaining_scopes jsonb NOT NULL CHECK(jsonb_typeof(remaining_scopes)='array'), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
  UNIQUE(resource_type,resource_id,deletion_revision)
);
-- Business invariants requiring transactions: ACL, DAG acyclicity, immutable manifests,
-- allowed state transitions, parent budget reservations, exact approval parameter binding,
-- artifact ownership, quota release/reconciliation. SQL alone does not enforce them.
